<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class UpbringingManagement extends Page{protected static ?string $navigationIcon='heroicon-o-cog';protected static ?string $navigationLabel='Управление отделом';protected static ?string $navigationGroup='Воспитательная работа';protected static string $view='filament.pages.upbringing-management';public array $stats=[];public array $tasks=[];public array $directions=[];public function mount():void{$p=request()->attributes->get('academic_period');if(!$p)return;$this->stats=['planned'=>DB::table('upbringing_events')->where('academic_period_id',$p->id)->where('status','planned')->count(),'completed'=>DB::table('upbringing_events')->where('academic_period_id',$p->id)->where('status','completed')->count(),'open_cases'=>DB::table('student_support_cases')->where('academic_period_id',$p->id)->where('status','!=','closed')->count(),'overdue_cases'=>DB::table('student_support_cases')->where('academic_period_id',$p->id)->where('status','!=','closed')->where('next_contact_on','<',today())->count(),'open_tasks'=>DB::table('upbringing_tasks')->where('academic_period_id',$p->id)->whereNotIn('status',['done','cancelled'])->count(),'overdue_tasks'=>DB::table('upbringing_tasks')->where('academic_period_id',$p->id)->whereNotIn('status',['done','cancelled'])->where('due_on','<',today())->count()];$this->tasks=DB::table('upbringing_tasks as t')->join('users as u','u.id','=','t.assigned_to')->where('t.academic_period_id',$p->id)->whereNotIn('t.status',['done','cancelled'])->select('t.id','t.title','t.priority','t.due_on','t.status','u.name as assigned_name')->orderBy('t.due_on')->limit(30)->get()->map(fn($x)=>(array)$x)->all();$this->directions=DB::table('upbringing_events')->where('academic_period_id',$p->id)->select('direction',DB::raw('COUNT(*) total'),DB::raw("SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END) completed"))->groupBy('direction')->orderByDesc('total')->get()->map(fn($x)=>(array)$x)->all();}}
